exactSources.buildTaperTodayTasks:
function buildTaperTodayTasks(days,total){
  const alloc=taperTaskAllocation(total,days);
  const routes=actionableReviewJourneys().length,due=dueQuestions().length;
  const weak=weakestSkill();

  if(days<=0){
    return [{
      type:'warmup',icon:'☀️',bg:'yellow',
      title:'受験前ウォームアップ 3問',
      desc:'既習問題を中心に3問だけ確認。新規教材・長時間模試・追い込みは行いません。',
      minutes:total
    }];
  }

  if(days===1){
    return [
      {
        type:'taperReview',icon:'🧠',bg:'green',
        title:'前日の復習 5問まで',
        desc:routes?`復習ルート ${routes}件から優先`:due?`期限/低保持 ${due}問から最大5問`:`「${weak}」を最大5問だけ確認`,
        minutes:alloc.review
      },
      {
        type:'warmup',icon:'🌙',bg:'yellow',
        title:'軽いウォームアップ 3問',
        desc:'解き慣れた既習問題だけで感覚を確認。新しい範囲は増やしません。',
        minutes:alloc.boss
      }
    ].filter(t=>t.minutes>0);
  }

  const focus=taperFocusRecommendation(days);
  const tasks=[
    {
      type:'taperReview',icon:'🧠',bg:'green',
      title:days<=3?'直前復習 5問':'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`期限/低保持 ${due}問を優先`:`今日の期限はなし。「${weak}」を維持`,
      minutes:alloc.review
    },
    {
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:alloc.lesson,focus
    }
  ];

  if(days>=4&&alloc.subjectB>=10){
    const b=nextBChoice(alloc.subjectB);
    tasks.push({
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`科目B：${b.title}`:b.mode==='security'?`科目B：${b.title}`:b.title,
      desc:'長時間の総合実戦ではなく、短い既習演習を1つ',
      minutes:alloc.subjectB,bmode:b.mode,bid:b.id
    });
  }else if(alloc.subjectB>0){
    tasks[1].minutes+=alloc.subjectB;
  }

  tasks.push({
    type:'boss',icon:'👑',bg:'yellow',
    title:'直前総合チェック',
    desc:'判断3問＋適用2問。新規知識ではなく、使えるかだけを5問で確認。',
    minutes:alloc.boss
  });
  return tasks.filter(t=>t.minutes>0);
}

exactSources.taperTaskAllocation:
function taperTaskAllocation(total,days){
  total=Math.max(5,Math.round(Number(total)||10));
  if(days<=0)return {review:0,lesson:0,subjectB:0,boss:total};
  if(days===1)return {review:Math.max(5,total-5),lesson:0,subjectB:0,boss:Math.min(5,total)};
  if(days<=3)return {review:10,lesson:Math.max(5,total-15),subjectB:0,boss:5};
  if(total<=30)return {review:10,lesson:10,subjectB:5,boss:5};
  return {review:15,lesson:10,subjectB:10,boss:Math.max(5,total-35)};
}

exactSources.renderHomeReviewCandidates:
function renderHomeReviewCandidates(){
  const root=document.getElementById('homeReviewCandidates');
  if(!root) return;
  const items=topReviewCandidates(3);
  if(!items.length){
    root.innerHTML='<div class="mini-card"><div class="big">🧠</div><b>学習データ待ち</b><div class="sub">問題を解くと、忘れそうな論点をここに表示します。</div></div>';
    return;
  }
  const icons={'基礎理論':'🔢','コンピュータ':'⚙️','データベース':'🗃️','ネットワーク':'🌐','セキュリティ':'🛡️','アルゴリズム':'🧩','マネジメント':'📋','ストラテジ':'📈'};
  root.innerHTML=items.map(q=>{
    const st=profile.qStats[q.id];
    const r=memoryRetention(st)??100;
    const timing=reviewTimingLabel(st);
    return `<div class="mini-card"><div class="big">${icons[q.cat]||'🧠'}</div><b>${escapeHtml(q.concept)}</b>
      <div class="sub">${escapeHtml(q.cat)}・${escapeHtml(q.cognitiveLevel||'')}・推定保持 ${r}%</div>
      <div class="progress" style="margin-top:10px"><div style="width:${r}%"></div></div>
      <div class="memory-risk" style="${timing.due?'':'color:var(--muted)'}">${escapeHtml(timing.text)}</div></div>`;
  }).join('');
}

